280	        recordChange("CLAIM_SPLIT", user, person, saved, saved.getNumber(), " into=" + number);
281	        recordChange("CLAIM_OPENED", user, person, split);
282	        rollup.recordChanges(user, before);
283	        return new Split(saved, split);
284	    }
285	
286	    /** What a split did: the claim split, keeping the rest of its amount, and the claim split off it. */
287	    public record Split(Claim original, Claim split) {
288	    }
