290	    /** Re-date an OPEN or PENDING claim. Its due-by stays as it was fixed and a figure a statement bound
291	     *  it to stays bound; its period follows the new date, and while the sheet's period numbering is in
292	     *  force a claim whose period changes takes the next number of its new period (or of claims in no
293	     *  period), its old number never given again. Refused unless the user is a steward of the sheet, and
294	     *  for a claim that is not OPEN or PENDING, a claim dated inside a closed period, a new date inside
295	     *  one, and a new date after its person's retirement. */
296	    @Transactional
297	    public Claim redate(String sheetId, String user, long id, LocalDate date) {
298	        Claim claim = claims.findForUpdate(id, sheetId)
299	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
300	        refuseIfClosed(sheetId, claim.getDate());
301	        refuseIfClosed(sheetId, date);
302	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
303	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-dates a claim.");
304	        }
305	        if (!claim.getStatus().isOpen()) {
306	            throw new ResponseStatusException(HttpStatus.CONFLICT,
307	                    "A " + claim.getStatus() + " claim cannot be re-dated; only an OPEN or PENDING one can.");
308	        }
309	        Person person = person(sheetId, claim.getPersonId());
310	        refuseIfRetired(person, date);
311	        Rollup.Snapshot before = rollup.snapshot(sheetId);
312	        LocalDate old = claim.getDate();
313	        Period oldPeriod = periodOf(sheetId, old);
314	        Period newPeriod = periodOf(sheetId, date);
315	        claim.redate(date);
316	        boolean samePeriod = oldPeriod == null ? newPeriod == null
317	                : newPeriod != null && oldPeriod.getId().equals(newPeriod.getId());
318	        if (!samePeriod && isPeriodNumbering(sheetId)) claim.setNumber(nextNumber(sheetId, claim));
319	        Claim saved = claims.saveAndFlush(claim);
320	        recordChange("CLAIM_REDATED", user, person, saved, saved.getNumber(), " old=" + old + " new=" + date);
321	        rollup.recordChanges(user, before);
322	        return saved;
323	    }
324	
325	    /** Raise a claim's proofs count by one. Refused for a SETTLED or VOID claim. No figure moves, so a
326	     *  claim dated inside a closed period may still have a proof added. */
327	    @Transactional
328	    public Claim addProof(String sheetId, String user, long id) {
329	        Claim claim = claims.findForUpdate(id, sheetId)
330	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
331	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
332	            throw new ResponseStatusException(HttpStatus.CONFLICT,
333	                    "A " + claim.getStatus() + " claim cannot have a proof added.");
334	        }
335	        Person person = person(sheetId, claim.getPersonId());
336	        claim.addProof();
337	        Claim saved = claims.saveAndFlush(claim);
338	        recordChange("CLAIM_PROOF_ADDED", user, person, saved, saved.getNumber(), " proofs=" + saved.getProofs());
339	        return saved;
340	    }
