342	    /** Move a DRAFT, OPEN or PENDING claim to another person on the sheet, as their newest claim. It
343	     *  keeps its number and date and loses any figure a statement bound it to (it is live again until
344	     *  its new person's next statement). Refused unless the sheet's permission matrix allows the user's
345	     *  role to reassign (by default, a steward), and for a
346	     *  settled or voided claim, a claim dated inside a closed period, a move to the claim's own person,
347	     *  or to a person retired by the claim's date. */
348	    @Transactional
349	    public Claim reassign(String sheetId, String user, long id, long toPersonId) {
350	        Claim claim = claims.findForUpdate(id, sheetId)
351	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
352	        refuseIfClosed(sheetId, claim.getDate());
353	        settings.refuseUnlessPermitted(sheetId, user, "reassign",
354	                "Your role may not move a claim to another person on this sheet.");
355	        if (claim.getStatus() != ClaimStatus.DRAFT && !claim.getStatus().isOpen()) {
356	            throw new ResponseStatusException(HttpStatus.CONFLICT,
357	                    "A " + claim.getStatus() + " claim cannot be moved to another person.");
358	        }
359	        Person from = person(sheetId, claim.getPersonId());
360	        Person to = person(sheetId, toPersonId);
361	        if (from.getId().equals(to.getId())) {
362	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is already " + to.getName() + "'s.");
363	        }
364	        refuseIfRetired(to, claim.getDate());
365	        Rollup.Snapshot before = rollup.snapshot(sheetId);
366	        claim.moveTo(to.getId(), claims.lastListed(sheetId) + 1, sheets.today(sheetId));
367	        Claim saved = claims.saveAndFlush(claim);
368	        recordChange("CLAIM_REASSIGNED", user, to, saved, saved.getNumber(),
369	                " from=" + from.getName() + " to=" + to.getName());
370	        rollup.recordChanges(user, before);
371	        return saved;
372	    }
