374	    /** Approve a PENDING claim: it is SETTLED, its due (its live figure and any late charge) frozen
375	     *  now. Refused unless the user is a steward of the sheet other than the one who opened it. */
376	    @Transactional
377	    public Claim approve(String sheetId, String user, long id) {
378	        Claim claim = pending(sheetId, user, id);
379	        if (user.equals(claim.getOpenedBy())) {
380	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
381	                    "The user who opened a claim cannot approve it.");
382	        }
383	        Person person = person(sheetId, claim.getPersonId());
384	        BigDecimal dueNow = due(sheetId, person, claim);
385	        refuseIfUnproven(sheetId, claim, dueNow);
386	        Rollup.Snapshot before = rollup.snapshot(sheetId);
387	        claim.setStatus(ClaimStatus.SETTLED);
388	        claim.setSettledDue(dueNow);
389	        logStatus(sheetId, user, person, claim);
390	        Claim saved = claims.saveAndFlush(claim);
391	        recordChange("CLAIM_APPROVED", user, person, saved, saved.getNumber(), " due=" + text(saved.getSettledDue()));
392	        notifyWatchers(user, person, saved);
393	        rollup.recordChanges(user, before);
394	        return saved;
395	    }
396	
397	    /** Re-settle a SETTLED claim: its due is frozen again at what it would be today as an open claim
398	     *  bound by no statement (today's rates, grades, floor and late charge). Refused unless the user is
399	     *  a steward of the sheet, and for a claim that is not SETTLED or is dated inside a closed period. */
400	    @Transactional
401	    public Claim resettle(String sheetId, String user, long id) {
402	        Claim claim = claims.findForUpdate(id, sheetId)
403	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
404	        refuseIfClosed(sheetId, claim.getDate());
405	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
406	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-settles a claim.");
407	        }
408	        if (claim.getStatus() != ClaimStatus.SETTLED) {
409	            throw new ResponseStatusException(HttpStatus.CONFLICT,
410	                    "A " + claim.getStatus() + " claim cannot be re-settled; only a SETTLED one can.");
411	        }
412	        Person person = person(sheetId, claim.getPersonId());
413	        BigDecimal old = claim.getSettledDue();
414	        BigDecimal dueNow = LateCharge.dueAsOpen(claim, dueNow(sheetId, person, claim),
415	                settings.floor(sheetId, claim.getDate()), sheets.today(sheetId),
416	                settings.dated(sheetId)::latePctOn, rounding(sheetId, claim));
417	        Rollup.Snapshot before = rollup.snapshot(sheetId);
418	        claim.setSettledDue(dueNow);
419	        logStatus(sheetId, user, person, claim);
420	        Claim saved = claims.saveAndFlush(claim);
421	        recordChange("CLAIM_RESETTLED", user, person, saved, saved.getNumber(),
422	                " old=" + text(old) + " new=" + text(saved.getSettledDue()));
423	        notifyWatchers(user, person, saved);
424	        rollup.recordChanges(user, before);
425	        return saved;
426	    }
427	
428	    /** Reject a PENDING claim for a reason: it is OPEN again, bound again by its person's last
429	     *  statement if that statement bound it. Refused unless the user is a steward of the sheet. */
430	    @Transactional
431	    public Claim reject(String sheetId, String user, long id, String reason) {
432	        Claim claim = pending(sheetId, user, id);
433	        Person person = person(sheetId, claim.getPersonId());
434	        Rollup.Snapshot before = rollup.snapshot(sheetId);
435	        claim.setStatus(ClaimStatus.OPEN);
436	        logStatus(sheetId, user, person, claim);
437	        Claim saved = claims.saveAndFlush(claim);
438	        recordChange("CLAIM_REJECTED", user, person, saved, saved.getNumber(), " reason=" + reason);
439	        rollup.recordChanges(user, before);
440	        return saved;
441	    }
442	
443	    /** The PENDING claim a steward approves or rejects, locked; refused when it is not PENDING, is
444	     *  dated inside a closed period, or the user is not a steward of the sheet. */
445	    private Claim pending(String sheetId, String user, long id) {
446	        Claim claim = claims.findForUpdate(id, sheetId)
447	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
448	        refuseIfClosed(sheetId, claim.getDate());
449	        if (claim.getStatus() != ClaimStatus.PENDING) {
450	            throw new ResponseStatusException(HttpStatus.CONFLICT,
451	                    "A " + claim.getStatus() + " claim is not waiting for approval.");
452	        }
453	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
454	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward approves or rejects a claim.");
455	        }
456	        return claim;
457	    }
