459	    /** How many days after its settlement a steward may still void a SETTLED claim. */
460	    private static final int VOID_SETTLED_DAYS = 7;
461	
462	    /** Refuse voiding a SETTLED claim unless the user is a steward of the sheet and the sheet's today is
463	     *  within {@value #VOID_SETTLED_DAYS} days of the claim's settlement, as its status log records it. */
464	    private void refuseUnlessSettledVoidable(String sheetId, String user, Claim claim) {
465	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
466	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward voids a settled claim.");
467	        }
468	        LocalDate settledOn = claim.settledOn();
469	        LocalDate today = sheets.today(sheetId);
470	        if (settledOn == null || today == null || today.isAfter(settledOn.plusDays(VOID_SETTLED_DAYS))) {
471	            throw new ResponseStatusException(HttpStatus.CONFLICT,
472	                    "A settled claim can only be voided within " + VOID_SETTLED_DAYS + " days of its settlement.");
473	        }
474	    }
