476	    /** The permission matrix's action for each status a claim is moved to by opening, settling or voiding it. */
477	    private static final Map<ClaimStatus, String> ACTIONS = Map.of(
478	            ClaimStatus.OPEN, "open", ClaimStatus.SETTLED, "settle", ClaimStatus.PENDING, "settle",
479	            ClaimStatus.VOID, "void");
480	
481	    private static final Map<ClaimStatus, String> EVENTS = Map.of(
482	            ClaimStatus.OPEN, "CLAIM_OPENED", ClaimStatus.PENDING, "CLAIM_PENDING",
483	            ClaimStatus.SETTLED, "CLAIM_SETTLED", ClaimStatus.VOID, "CLAIM_VOIDED");
484	
485	    private static String text(BigDecimal due) {
486	        return due == null ? "n/a" : due.toPlainString();
487	    }
