489	    /** The number a claim takes as it is opened: while the sheet's period numbering is in force (its
490	     *  today on or after the setting's date), the next of the claim's period, <period name>-<n>, or of
491	     *  claims in no period, X-<n>; otherwise the sheet's next sheet-wide number. */
492	    private String nextNumber(String sheetId, Claim claim) {
493	        if (!isPeriodNumbering(sheetId)) {
494	            return Integer.toString(sheets.nextClaimNumber(sheetId));
495	        }
496	        Period period = periodOf(sheetId, claim.getDate());
497	        if (period == null) return "X-" + sheets.nextSequenceNumber(sheetId, "none");
498	        return period.getName() + "-" + sheets.nextSequenceNumber(sheetId, "period:" + period.getId());
499	    }
