501	    /** Whether the sheet's period numbering is in force: its today on or after the setting's date. */
502	    private boolean isPeriodNumbering(String sheetId) {
503	        LocalDate from = settings.periodNumberingFrom(sheetId);
504	        return from != null && !sheets.today(sheetId).isBefore(from);
505	    }
506	
507	    /** The sheet's period whose dates contain the date; null when none does. */
508	    private Period periodOf(String sheetId, LocalDate date) {
509	        return periods.findBySheetIdOrderByFromAsc(sheetId).stream()
510	                .filter((p) -> p.contains(date)).findFirst().orElse(null);
511	    }
512	
513	    /** Refuse settling or approving a claim with no proofs whose due is above the sheet's proof threshold
514	     *  in force on the claim's date (a due of n/a, or no threshold, needs none). */
515	    private void refuseIfUnproven(String sheetId, Claim claim, BigDecimal due) {
516	        if (due == null || claim.getProofs() > 0) return;
517	        BigDecimal threshold = settings.proofThreshold(sheetId, claim.getDate());
518	        if (threshold != null && due.compareTo(threshold) > 0) {
519	            throw new ResponseStatusException(HttpStatus.CONFLICT,
520	                    "The claim's due is above the proof threshold of " + threshold.toPlainString()
521	                            + "; add a proof before it is settled.");
522	        }
523	    }
524	
525	    /** Refuse opening a claim with an empty note whose due is above the sheet's note threshold in force
526	     *  on the claim's date (a due of n/a, or no threshold, needs none). */
527	    private void refuseIfUnnoted(String sheetId, Claim claim, BigDecimal due) {
528	        if (due == null || (claim.getNote() != null && !claim.getNote().isBlank())) return;
529	        BigDecimal threshold = settings.noteThreshold(sheetId, claim.getDate());
530	        if (threshold != null && due.compareTo(threshold) > 0) {
531	            throw new ResponseStatusException(HttpStatus.CONFLICT,
532	                    "The claim's due is above the note threshold of " + threshold.toPlainString()
533	                            + "; add a note before it is opened.");
534	        }
535	    }
536	
537	    /** Whether the user is a clerk settling a claim whose due is above the sheet's clerk limit. */
538	    private boolean isAboveClerkLimit(String sheetId, String user, BigDecimal due) {
539	        if (due == null || settings.roleOf(sheetId, user) == Role.STEWARD) return false;
540	        BigDecimal limit = settings.clerkLimit(sheetId);
541	        return limit != null && due.compareTo(limit) > 0;
542	    }
543	
544	    /** Refuse a change to a claim dated inside a closed period. The sheet is locked first, as closing
545	     *  a period locks it, so a claim cannot change in a period while it is being closed. */
546	    private void refuseIfClosed(String sheetId, LocalDate date) {
547	        sheetRows.findForUpdate(sheetId);
548	        if (periods.isClosedOn(sheetId, date)) {
549	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim is dated inside a closed period.");
550	        }
551	    }
552	
553	    /** Refuse a correction (a negative amount) unless it names, by number, a settled claim of the same person. */
554	    private void refuseIfNotCorrecting(String sheetId, long personId, BigDecimal amount, String corrects) {
555	        if (amount.signum() >= 0) return;
556	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
557	                .filter(c -> c.getStatus() == ClaimStatus.SETTLED).isPresent();
558	        if (!settled) {
559	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
560	                    "A negative amount must name, by number, a settled claim of the same person that it corrects.");
561	        }
562	    }
563	
564	    /** Refuse a claim dated after its person's retirement date. */
565	    private static void refuseIfRetired(Person person, LocalDate date) {
566	        if (person.isRetiredOn(date)) {
567	            throw new ResponseStatusException(HttpStatus.CONFLICT,
568	                    "The claim is dated after " + person.getName() + " retired.");
569	        }
570	    }
571	
572	    private Person person(String sheetId, long personId) {
573	        return people.findByIdAndSheetId(personId, sheetId)
574	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
575	    }
576	
577	    /** What is due on the claim now: the due fixed when it was settled, else the greater of the floor in
578	     *  force on its date and its figure with the late charge on top while it is open and overdue (the charge
579	     *  is never bound by a statement; a correction has no floor); null when the figure is n/a. */
580	    public BigDecimal due(String sheetId, Person person, Claim claim) {
581	        return LateCharge.dueOf(claim, figure(sheetId, person, claim), settings.floor(sheetId, claim.getDate()),
582	                sheets.today(sheetId),
583	                settings.dated(sheetId)::latePctOn, rounding(sheetId, claim));
584	    }
585	
586	    /** The figure under the claim's due, before any late charge and floor: the due fixed when it was settled, else the figure
587	     *  its person's last statement bound it to (unless it is PENDING, which no statement binds), else its live due;
588	     *  null when that is n/a. */
589	    public BigDecimal figure(String sheetId, Person person, Claim claim) {
590	        if (claim.getSettledDue() != null) return claim.getSettledDue();
591	        if (claim.isBound()) return claim.getStatedDue();
592	        return dueNow(sheetId, person, claim);
593	    }
594	
595	    /** The claim's rate figure now: at the rate in force on the claim's date of its person's grade in
596	     *  force on that date, rounded as the claim's {@link Rounding} decides, before any late charge and
597	     *  floor; null when no rate of the grade applies by then. */
598	    private BigDecimal dueNow(String sheetId, Person person, Claim claim) {
599	        Rate rate = rates.inForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate());
600	        if (rate == null) return null;
601	        return claim.getAmount().multiply(rate.getPct()).divide(BigDecimal.valueOf(100), 2,
602	                rounding(sheetId, claim));
603	    }
604	
605	    /** How the claim's live figures round under the sheet's policy date: by the date of the claim a
606	     *  correction corrects, else by its own. */
607	    private RoundingMode rounding(String sheetId, Claim claim) {
608	        return rounding(sheetId, claim, sheets.today(sheetId));
609	    }
610	
611	    /** How the claim's figures round under the sheet's policy date with the date given standing in for
612	     *  the sheet's today. */
613	    public RoundingMode rounding(String sheetId, Claim claim, LocalDate today) {
614	        Claim corrected = claim.isCorrection() && claim.getCorrects() != null
615	                ? claims.findBySheetIdAndPersonIdAndNumber(sheetId, claim.getPersonId(), claim.getCorrects()).orElse(null)
616	                : null;
617	        return Rounding.of(Rounding.dateOf(claim, corrected),
618	                Rounding.policyDate(settings.policyDate(sheetId), today));
619	    }
620	
621	    /** Log the status the claim has just taken, with its due as worked out now. */
622	    private void logStatus(String sheetId, String user, Person person, Claim claim) {
623	        claim.logStatus(user, sheets.today(sheetId), due(sheetId, person, claim));
624	    }
625	
626	    private void recordChange(String event, String user, Person person, Claim claim) {
627	        recordChange(event, user, person, claim, claim.getNumber(), "");
628	    }
629	
630	    /** The claim's audit line; a claim with a number carries it, then any extra fields. */
631	    private void recordChange(String event, String user, Person person, Claim claim, String number, String extra) {
632	        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
633	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
634	                + (number == null ? "" : " number=" + number) + extra);
635	    }
636	
637	    /** Tell each user watching the person, in the order they started watching, that the claim was settled. */
638	    private void notifyWatchers(String user, Person person, Claim claim) {
639	        for (PersonWatch watch : watches.findByPersonIdOrderByIdAsc(person.getId())) {
640	            audit.recordOnCommit("NOTIFY sheet=" + claim.getSheetId() + " by=" + user + " user=" + watch.getUserName()
641	                    + " person=" + person.getName() + " number=" + claim.getNumber());
642	        }
643	    }
644	
645	    private LocalDate dateOr(String sheetId, LocalDate date) {
646	        return date != null ? date : sheets.today(sheetId);
647	    }
648	
649	    /** The date a new claim given none takes: the sheet's entry date while it is set, else its today. */
650	    private LocalDate entryDateOr(String sheetId) {
651	        LocalDate entry = settings.entryDate(sheetId);
652	        return entry != null ? entry : sheets.today(sheetId);
653	    }
654	
655	    private static String noteOf(String note) {
656	        return note == null ? "" : note.trim();
657	    }
658	}
